/* Governance: documented mechanisms, explicit scope, and a local four-eyes demonstration. */
const Q_CAPABILITIES=[
['iam','Identidade e acesso','Reconhecer a pessoa, a organização e as permissões que acompanham a ação.'],
['api-keys','Acesso entre sistemas','Delimitar o que uma integração pode consultar ou realizar.'],
['decision-engine','Regras com referência','Identificar a versão de política utilizada em uma avaliação.'],
['audit-trail','Histórico de alterações','Consultar os eventos publicados, com contexto sobre o que mudou.'],
['biometrics','Verificação de identidade','Associar a avaliação e suas evidências à sessão de verificação.'],
['feature-flags','Mudança por etapas','Controlar a exposição de uma função conforme a configuração do produto.']
];
Object.assign(X_CAPTURE_META,{'bank-access.jpg':{product:'governance',title:'Acesso / Pessoas, papéis e estado',desc:'Interface de referência do console Banking, com pessoas, papéis e estados de acesso.',type:'Console',origin:'Protótipo no guia Banking · dados de exemplo · data original da captura não informada'}});
function qHeroArt(){return `<svg class="q-hero-art" viewBox="0 0 740 620" role="img" aria-label="Duas responsabilidades sustentam uma estrutura comum: uma escultura de equilíbrio em roxo e laranja"><defs><linearGradient id="gov-beam" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#ffc183"/><stop offset="1" stop-color="#e68c49"/></linearGradient><linearGradient id="gov-base"><stop stop-color="#dbc9e7"/><stop offset="1" stop-color="#a582be"/></linearGradient><filter id="gov-shadow"><feGaussianBlur stdDeviation="15"/></filter></defs><ellipse cx="370" cy="485" rx="220" ry="40" fill="#4c315e" opacity=".12" filter="url(#gov-shadow)"/><g fill="none" stroke="#d0c0d9" stroke-width=".7"><path d="M80 435L367 269L656 436L369 602Z"/><path d="M152 477L439 311M224 519L511 353M296 561L583 395M152 394L441 561M224 352L513 519M296 310L585 477" stroke-dasharray="2 8"/></g><path d="M260 441L369 378L478 441L369 504Z" fill="url(#gov-base)"/><path d="M260 441V463L369 526V504Z" fill="#a27dbb"/><path d="M369 504L478 441V463L369 526Z" fill="#76508f"/><path d="M302 417L369 215L436 417Z" fill="#a381b9"/><path d="M369 215L392 228L459 430L436 417Z" fill="#70468b"/><path d="M302 417L369 456L436 417Z" fill="#8c65a6"/><g class="q-balance-beam"><path d="M124 219L150 192L610 265L584 292Z" fill="url(#gov-beam)"/><path d="M124 219V240L584 313V292Z" fill="#d27a3c"/><path d="M584 292L610 265V286L584 313Z" fill="#b45d2c"/><g fill="none" stroke="#ab8cbd" stroke-width="1.6"><path d="M179 247V361M558 307V421"/></g><g class="q-tray-left"><ellipse cx="179" cy="370" rx="78" ry="39" fill="#8d68a6"/><path d="M101 361V375C101 427 257 427 257 375V361Z" fill="#9c7ab4"/><ellipse cx="179" cy="361" rx="78" ry="39" fill="#dfcee9"/><path d="M137 359L178 335L220 359L179 383Z" fill="#f8f3ec"/><path d="M137 359V368L179 392V383Z" fill="#c4acd3"/><path d="M179 383L220 359V368L179 392Z" fill="#ad8dbf"/></g><g class="q-tray-right"><ellipse cx="558" cy="430" rx="78" ry="39" fill="#8d68a6"/><path d="M480 421V435C480 487 636 487 636 435V421Z" fill="#9c7ab4"/><ellipse cx="558" cy="421" rx="78" ry="39" fill="#dfcee9"/><circle cx="558" cy="418" r="28" fill="#f1b879"/><path d="M544 419L554 429L573 405" fill="none" stroke="#fff3e3" stroke-width="2.5"/></g></g><circle cx="370" cy="231" r="10" fill="#f4d16d"/><g fill="#ae92bc" font-family="monospace" font-size="9" letter-spacing="1.5"><text x="101" y="460">PROPÓSITO</text><text x="517" y="510">RESPONSABILIDADE</text><text x="266" y="569">CONFIANÇA / COM ESTRUTURA</text></g></svg>`}
function qApproval(state='new',actor='requester',denied=false){const pending=state==='pending',closed=['approved','refused'].includes(state);return `<div class="q-request-sheet"><div class="q-request-top"><span>EXEMPLO / MUDANÇA DE ACESSO SENSÍVEL</span><span class="q-request-status ${state}">${{new:'Pedido ainda não criado',pending:'Aguardando revisão',approved:'Aprovado na simulação',refused:'Recusado na simulação'}[state]}</span></div><h3>Conceder um papel<br>de acesso sensível.</h3><p>Uma pessoa solicita. Outra pessoa autorizada revisa, na mesma organização.</p><div class="q-people"><div class="${actor==='requester'?'q-person-active':''}"><span class="q-person-icon">A</span><strong>Solicitante</strong><small>Prepara o pedido</small></div><span class="q-people-connection" aria-hidden="true">→</span><div class="${actor==='reviewer'?'q-person-active':''}"><span class="q-person-icon q-person-reviewer">B</span><strong>Revisor</strong><small>Confere e decide</small></div></div><label class="q-actor-label">Quem está agindo na demonstração?<select id="q-actor"><option value="requester" ${actor==='requester'?'selected':''}>Pessoa A / Solicitante</option><option value="reviewer" ${actor==='reviewer'?'selected':''}>Pessoa B / Revisor autorizado</option></select></label><div class="q-request-actions">${state==='new'?`<button data-q-request ${actor!=='requester'?'disabled':''}>Criar pedido demonstrativo <span>↗</span></button>`:pending?`<button data-q-approve>Aprovar pedido <span>✓</span></button><button data-q-refuse>Recusar</button>`:`<p class="q-terminal-state">${state==='approved'?'A pessoa B aprovou o pedido na demonstração.':'A pessoa B recusou o pedido na demonstração.'} Nenhum acesso real foi alterado.</p>`}</div><p class="q-request-feedback" role="status">${denied?'Quem solicita não pode aprovar ou recusar o próprio pedido. Troque para a pessoa B para continuar.':state==='new'?'Comece pela pessoa A e prepare o pedido.':pending?'O pedido aguarda uma segunda pessoa autorizada.':closed?'Demonstração concluída. Você pode reiniciar para explorar outro resultado.':''}</p><button class="q-reset" data-q-reset>Reiniciar exemplo ↺</button></div>`}
function qPage(blocks){return `<div class="q-page"><section class="q-hero"><div class="wrap"><div><span class="label">Catalisa / Governança</span><h1>Confiança tem<br><em>estrutura.</em></h1><p>Quem pode agir. O que precisa de revisão. Como entender o que aconteceu. Governança conecta essas respostas à operação.</p><a class="text-link" href="#responsabilidades">Explore as responsabilidades ↓</a></div><div class="q-hero-object">${qHeroArt()}</div></div><div class="q-hero-foot wrap"><span>Mais clareza para agir.<br>Mais contexto para responder.</span><button data-q-motion aria-pressed="false">Ⅱ Pausar movimento</button></div></section><section class="q-editorial wrap"><span class="label">Uma responsabilidade compartilhada</span><h2>A base oferece mecanismos.<br><em>A operação dá direção.</em></h2><div><p>A governança aparece no desenho de cada jornada: nos acessos, nas regras, na revisão e nos registros que ajudam a reconstruir o trabalho.</p><p>A plataforma conecta essas capacidades. Cada organização define sua política, configura os controles e valida se eles atendem ao contexto em que vai operar.</p></div></section><section class="q-responsibilities" id="responsabilidades"><div class="wrap"><div><span class="label">Antes, durante e depois</span><h2>Uma ação precisa<br>fazer sentido<br>em cada momento.</h2></div><div class="q-responsibility-index">${[['01','Antes de agir','Identificar a pessoa e a organização, conferir o papel e delimitar quais informações e ações estão disponíveis.','iam','Identidade e permissões'],['02','Quando a ação exige revisão','Definir o que precisa de outra pessoa, em qual etapa e com qual autoridade. O desenho da aprovação faz parte da jornada.','iam','Política de acesso'],['03','Depois de acontecer','Relacionar a ação aos registros disponíveis, à mudança realizada e à regra que orientou o resultado.','audit-trail','Histórico e evidências']].map(([n,t,p,slug,l])=>`<article><span>${n}</span><div><h3>${t}</h3><p>${p}</p>${ca('/capacidades/'+slug+'/',l)}</div></article>`).join('')}</div></div></section><section class="q-approval-section wrap"><div class="q-section-heading"><div><span class="label">Duas pessoas. Responsabilidades diferentes.</span><h2>Um pedido não precisa<br>ser a própria aprovação.</h2></div><p>Experimente a separação entre<br>quem solicita e quem revisa.</p></div><div class="q-approval-layout"><div class="q-approval-explanation"><span class="label">Uma leitura do princípio de quatro olhos</span><h3>Prepare.<br>Confira.<br>Decida.</h3><p>O IAM documenta uma política de revisão por segunda pessoa para mudanças de acesso sensível cobertas por esse controle.</p><p>Quando a política da organização está ativada, a alteração gera um pedido. A revisão cabe a outra pessoa autorizada da mesma organização.</p><p class="q-demo-boundary">Este é um exemplo local e ilustrativo. Não altera permissões. O escopo real depende da política ativada e das ações cobertas no IAM.</p>${ca('https://docs.catalisa.app/blocks/iam/','Veja o escopo documentado')}</div><div id="q-approval" aria-label="Exemplo interativo de revisão de acesso">${qApproval()}</div></div></section><section class="q-evidence"><div class="wrap"><div class="q-evidence-heading"><span class="label">Quando chega a pergunta: o que aconteceu?</span><h2>O histórico precisa<br>ajudar a contar a história.</h2><p>Uma alteração ganha contexto quando é possível relacionar quem agiu, o que mudou e qual referência foi utilizada.</p></div><div class="q-dossier"><div class="q-dossier-cover"><span>LEITURA ILUSTRATIVA / SEM DADOS REAIS</span><h3>Uma mudança.<br>Mais de uma<br>pergunta.</h3><p>Os registros vêm das capacidades responsáveis. O exemplo organiza as perguntas que uma investigação precisa responder.</p></div><div class="q-dossier-records">${[['Quem?','Pessoa, sistema e organização','O contexto de identidade acompanha a ação conforme o mecanismo utilizado.'],['O quê?','Recurso e alteração','O histórico pode mostrar o estado anterior e o que ficou depois.'],['Com qual regra?','Referência e versão','Uma avaliação pode ser relacionada à versão da política que foi publicada.'],['O que está coberto?','Eventos efetivamente registrados','A trilha depende dos eventos que cada capacidade publica. Cobertura precisa ser conferida.']].map(([q,t,p])=>`<article><span>${q}</span><div><h4>${t}</h4><p>${p}</p></div></article>`).join('')}</div></div><div class="q-evidence-note"><p>Audit Trail está em Beta. Retenção declarada não significa eliminação automática; configuração, coleta e procedimentos operacionais precisam estar ativos. A integridade verificável da trilha tem limites documentados.</p>${ca('https://docs.catalisa.app/blocks/audit-trail/','Consulte a cobertura e os limites')}</div></div></section><section class="q-contexts wrap"><span class="label">O princípio ganha contexto</span><h2>A governança acompanha<br>o tipo de trabalho.</h2><div class="q-context-stories"><article><span>01 / Acesso entre organizações</span><h3>A mesma plataforma.<br>Fronteiras de acesso próprias.</h3><p>Identidade, organização e permissões ajudam a delimitar o contexto em que cada pessoa atua. Os acessos de uma integração também precisam de escopo próprio.</p><div>${ca('/capacidades/iam/','IAM')}${ca('/capacidades/api-keys/','API Keys')}</div></article><article><span>02 / Política de negócio</span><h3>A regra muda.<br>A referência permanece.</h3><p>Políticas versionadas ajudam a relacionar uma avaliação à regra utilizada naquele momento. A preparação dos dados e a publicação da política têm responsabilidades diferentes.</p><div>${ca('/capacidades/decision-engine/','Decision Engine')}${ca('/ecossistema/decision/','Decision')}</div></article><article><span>03 / Atendimento com copiloto</span><h3>A inteligência apoia.<br>O profissional revisa.</h3><p>O perfil pode definir apoio, registros e ações para momentos diferentes do atendimento. A revisão e a liberação dos próximos passos pertencem ao desenho dessa experiência.</p><div>${ca('/agentes/','Agentes IA')}${ca('/studio/#perfis','Perfis de atendimento')}</div></article></div></section><section class="q-access-exhibit"><div class="wrap"><div><span class="label">Uma visão dos acessos</span><h2>Pessoas, papéis<br>e estados precisam<br>ser compreensíveis.</h2><p>Uma interface ajuda a equipe a conferir quem participa da operação e em qual condição. A permissão continua sendo aplicada pela capacidade responsável.</p><p class="q-screen-note">Interface de referência do guia Banking: protótipo com dados de exemplo. A tela não comprova a disponibilidade de todos os fluxos apresentados.</p>${ca('/ecossistema/banking/','Explore o Banking Platform')}</div><figure class="q-access-print"><div><span>Console / Pessoas e acesso</span><small>Ampliar ↗</small></div><button data-gallery-file="bank-access.jpg" data-gallery-product="governance" aria-label="Ampliar referência de pessoas e acessos"><img src="/assets/screens/bank-access.jpg" alt="Protótipo do console Banking com pessoas, papéis e estados de acesso" loading="lazy"></button><figcaption>Material do guia Banking · dados de exemplo · data original não informada</figcaption></figure></div></section><section class="q-capabilities wrap"><div class="q-section-heading"><div><span class="label">Capacidades por trás dos controles</span><h2>Cada mecanismo tem<br>um papel e um estágio.</h2></div><p>Explore o propósito da capacidade<br>e consulte os limites antes de integrar.</p></div><div class="q-capability-list">${Q_CAPABILITIES.map(([slug,t,p])=>{const b=blocks.find(x=>x.slug===slug);return `<a href="/capacidades/${slug}/"><span class="q-capability-name">${ce(b?.name||t)}</span><div><h3>${t}</h3><p>${p}</p></div><span class="q-maturity">${ce(b?.status||'Consulte a documentação')}</span><i aria-hidden="true">↗</i></a>`}).join('')}</div></section><section class="q-questions wrap"><div><span class="label">Para avaliar com clareza</span><h2>Confiança também<br>é conhecer o escopo.</h2></div><div>${[
['Ter uma trilha significa registrar tudo?','Não. A trilha depende dos eventos publicados pelas capacidades. Verifique quais ações estão cobertas, se a coleta está habilitada e quais registros estão disponíveis na sua composição.'],
['O princípio de quatro olhos vale para qualquer ação?','O mecanismo documentado no IAM cobre mudanças de acesso sensível previstas pela política, quando ativada. Aprovação de pagamentos, documentos ou outras ações precisa de desenho e validação próprios.'],
['Um agente pode usar tudo porque recebeu uma instrução?','As instruções orientam o comportamento. O acesso às ferramentas e às ações precisa de controles próprios, configurados para o papel e o contexto em que o agente participa.'],
['Definir um prazo de retenção já elimina os registros?','Não. A documentação do Audit Trail distingue a política declarada da execução do procedimento de eliminação. A operação precisa configurar e acompanhar esse processo, considerando os limites documentados.'],
['Esses mecanismos garantem conformidade por si só?','Eles fornecem recursos para o desenho de controles. Política, configuração, cobertura, operação e avaliação de suficiência dependem do contexto da organização. Não equivalem a uma certificação automática.'],
['Por onde começar a avaliação?','Escolha uma jornada. Identifique quem atua, que informações utiliza, quais ações exigem revisão e que registros precisam estar disponíveis. Cruze essa necessidade com o estágio e os limites das capacidades escolhidas.']
].map(([q,a])=>`<details><summary>${q}<span aria-hidden="true">＋</span></summary><p>${a}</p></details>`).join('')}</div></section><section class="q-closing"><div class="wrap"><span class="label">Autonomia que encontra responsabilidade</span><h2>Construa o próximo passo.<br>Com clareza para responder.</h2><div>${ca('/arquitetura/','Entenda a arquitetura')}${ca('/desenvolvedores/','Explore os contratos')}${ca('/contato/','Converse sobre a composição')}</div></div></section></div>`}
const qOriginalPage=cPage;cPage=function(route,blocks){return route==='/governanca/'?qPage(blocks):qOriginalPage(route,blocks)};
function qBind(){const root=document.querySelector('.q-page');if(!root)return;const panel=document.getElementById('q-approval');let state='new',actor='requester',denied=false;const render=()=>panel.innerHTML=qApproval(state,actor,denied);panel.addEventListener('change',e=>{if(e.target.id==='q-actor'){actor=e.target.value;denied=false;render();panel.querySelector('#q-actor').focus({preventScroll:true})}});panel.addEventListener('click',e=>{if(e.target.closest('[data-q-request]')&&state==='new'&&actor==='requester'){state='pending';denied=false;render();panel.querySelector('#q-actor').focus({preventScroll:true})}if(e.target.closest('[data-q-approve],[data-q-refuse]')&&state==='pending'){if(actor==='requester')denied=true;else{state=e.target.closest('[data-q-approve]')?'approved':'refused';denied=false}render();panel.querySelector(denied?'#q-actor':'[data-q-reset]').focus({preventScroll:true})}if(e.target.closest('[data-q-reset]')){state='new';actor='requester';denied=false;render();panel.querySelector('[data-q-request]').focus({preventScroll:true})}});root.querySelector('[data-q-motion]').addEventListener('click',e=>{const paused=root.classList.toggle('q-motion-paused');e.currentTarget.setAttribute('aria-pressed',String(paused));e.currentTarget.textContent=paused?'▶ Retomar movimento':'Ⅱ Pausar movimento'})}
if(typeof document!=='undefined')document.addEventListener('DOMContentLoaded',qBind);
